                       '            <h2>Early Life in South Side Chicago and Her Exact Age</h2>\n'
                       '            <p>Juanita Vanoy was born on <strong>June 13, 1959</strong>, in the South Side '
                       'neighborhood of Chicago, Illinois. Growing up as the fifth of six daughters in a close-knit, '
                       'hardworking family, she developed a sharp work ethic and self-reliance from a young age. Her '
                       'parents instilled values of modesty, educational dedication, and personal responsibility that '
                       'remained the bedrock of her character. As of 2026, Juanita Vanoy is <strong>67 years '
                       'old</strong>.</p>\n'
                       '\n'
                       '            <p>During her youth, Vanoy pursued commercial modeling while taking on serious '
                       'professional roles to build financial independence. She worked as an executive secretary at '
                       'the American Bar Association and later transitioned into the mortgage industry as a licensed '
                       'loan officer with a prominent financial firm in downtown Chicago. Her practical business '
                       'acumen, analytical mindset, and composure under pressure would serve as her greatest assets '
                       'during the whirlwind decades that lay ahead.</p>\n'
                       '\n'
                       '            <h2>Meeting Michael Jordan and Their 17-Year Marriage</h2>\n'
                       "            <p>In March 1985, during Michael Jordan's sensational rookie season with the "
                       'Chicago Bulls, fate brought the two together. They were introduced by a mutual friend at a '
                       "Bennigan's restaurant in Chicago following a Bulls game. Unlike many around the emerging "
                       'superstar, Vanoy was unimpressed by athletic celebrity. She valued substance, personal '
                       'integrity, and conversation—qualities that immediately captivated the young North Carolina '
                       'product.</p>\n'
                       '\n'
                       '            <p>Their relationship blossomed quietly over several years as Jordan ascended to '
                       "superstar status. On New Year's Eve in 1987, Jordan proposed to Vanoy at Nick's Fishmarket in "
                       'downtown Chicago. On September 2, 1989, the couple exchanged vows in an intimate ceremony at A '
                       'Little White Wedding Chapel in Las Vegas, Nevada, accompanied by their infant son, Jeffrey. In '
                       'a thoughtful parallel to the high-profile athletic relationships detailed in our profiles of '
                       '<a href="/marlene-knaus/">Marlene Knaus</a> and <a href="/cindy-deangelis-grossman/">Cindy '
                       'DeAngelis Grossman</a>, Vanoy became an indispensable confidante who kept household life calm '
                       'while public arenas erupted in adulation.</p>\n'
                       '\n'
                       '            <p>Throughout their 17-year marriage, Vanoy was a fixture courtside at Chicago '
                       "Stadium and later the United Center, cheering through the Bulls' historic 1991&ndash;1993 and "
                       "1996&ndash;1998 three-peat championship runs. Behind closed doors, she managed the family's "
                       'expansive 56,000-square-foot Highland Park estate, shielded their three children from '
                       'aggressive paparazzi, and co-founded major civic initiatives across Illinois.</p>\n'
                       '\n'
                       '            <p>When Jordan faced devastating personal grief in the summer of 1993 following '
                       'the tragic murder of his father, James Jordan Sr., it was Juanita who provided the emotional '
                       'sanctuary and structural stability Michael needed to mourn away from the spotlight. During '
