                       'divorce settlements in sports and entertainment history. Both Jordan and Vanoy issued a joint '
                       'statement emphasizing their continued friendship and shared devotion to co-parenting their '
                       'three children.</p>\n'
                       '\n'
                       '            <p>Legal analysts noted that the substantial settlement reflected not merely '
