                       '\n'
                       '            <p>Working in law firms provided Burditt with a distinct perspective on celebrity '
                       'and contracts. When media interest surged around her engagement to Harrison, she approached '
                       'the public curiosity with the same calm neutrality she applied to legal briefs, ensuring her '
