                       '            <h2>Early Life in Ohio, Roots, and Age in 2026</h2>\n'
                       '            <p>Diane Lou Oswald was born in March 1937 in the historic city of Lebanon, '
                       'located in Warren County, Ohio. She was raised in a principled Midwestern household where '
                       'community service, modest living, and Presbyterian church attendance were cornerstones of '
                       'daily life. As of 2026, Diane Lou Oswald is <strong>89 years old</strong>.</p>\n'
                       '\n'
                       '            <p>Growing up in Lebanon, Ohio, Diane was immersed in a tight-knit Midwestern '
                       'community where neighbors supported one another through economic shifts. Her father, an '
                       'industrious local craftsman, and her mother instilled in her a profound work ethic that '
                       'prioritized honesty above material wealth. When Diane returned to Lebanon with her young sons '
                       'after leaving Texas, the community provided a safe haven where Woody, Brett, and Jordan could '
                       "attend local schools without the intrusive stigma of their father's notoriety.</p>\n"
                       '\n'
                       "            <p>During Woody's years at Lebanon High School, Diane worked tirelessly to balance "
                       "strict maternal discipline with creative freedom. Recognizing Woody's natural gifts for "
