                       '            <p class="lead-paragraph" style="font-size: 1.18rem; line-height: 1.75; color: '
                       'var(--text-primary); margin-bottom: 24px; font-weight: 500;">Kelly Tisdale is an accomplished '
                       'American scenic artist, entrepreneur, and former restaurateur who is widely recognized as the '
                       'longtime wife of beloved Canadian-American comedy icon, actor, and filmmaker Mike Myers. While '
                       "Myers has entertained generations through landmark franchises such as <em>Wayne's World</em>, "
                       '<em>Austin Powers</em>, and <em>Shrek</em>, Tisdale has carved out her own unique professional '
                       'journey within the worlds of television production, visual artistry, and progressive Manhattan '
                       'business ventures.</p>\n'
                       '\n'
                       '            <p>Unlike many celebrity spouses who embrace the public spotlight, Kelly Tisdale '
                       'has deliberately maintained a grounded, private lifestyle centered on creative endeavors, '
                       'family stability, and artistic authenticity. Together with Mike Myers, she has built an '
                       'enduring marriage spanning more than sixteen years, establishing a peaceful home environment '
                       'for their three children away from the relentless scrutiny of Hollywood red carpets.</p>\n'
                       '\n'
                       '            <h2>Who Is Kelly Tisdale?</h2>\n'
                       '            <p>Kelly Tisdale is an American creative professional with a diverse background in '
                       'scenic design, hospitality management, and independent entrepreneurship. During the early '
                       "2000s, she became a prominent fixture in New York City's burgeoning organic food movement as "
                       'the co-founder and managing partner of TeaNY, a trailblazing vegan café and premium beverage '
                       "brand launched alongside musician Moby in Manhattan's Lower East Side.</p>\n"
                       '\n'
