                       '            <h2>Early Life, Background, and Age</h2>\n'
                       '            <p>Kelly Tisdale was born on March 27, 1977, in Templeton, Massachusetts. Raised '
                       'in New England, she developed an early passion for decorative painting, spatial design, and '
                       'fine arts. Her New England upbringing instilled a deep sense of modesty, self-reliance, and '
                       'artistic dedication that continued to guide her throughout her adult life and career in New '
                       'York City.</p>\n'
                       '\n'
                       '            <p>As of 2026, Kelly Tisdale is <strong>49 years old</strong>, celebrating her '
                       'birthday each year on March 27 under the Aries zodiac sign. Throughout her twenties, Tisdale '
                       'studied fine arts and specialized production techniques, preparing her for demanding technical '
                       'roles on major commercial and entertainment sets across the East Coast.</p>\n'
                       '\n'
                       '            <h2>Career as a Scenic Artist and Co-Founder of TeaNY with Moby</h2>\n'
                       '            <p>Before achieving international recognition as an entrepreneur, Kelly Tisdale '
                       'established herself as a skilled scenic artist in the television and film industry. In scenic '
                       'artistry, professionals are tasked with painting backdrops, creating intricate textures, and '
                       'establishing authentic atmospheric aesthetics for studios and stage productions. Her technical '
                       'credits include working on television productions such as the late-1990s anthology series '
                       '<em>Erotic Confessions</em>, where her visual design skills received widespread praise among '
                       'crew members.</p>\n'
                       '\n'
                       '            <p>In May 2002, Tisdale took a bold entrepreneurial leap that redefined her public '
                       'profile. Partnering with longtime friend and electronic music pioneer Richard Melville Hall '
                       '(better known worldwide as <strong>Moby</strong>), she co-founded <strong>TeaNY</strong>, an '
                       "intimate, stylish tea room and vegan cafe situated at 90 Rivington Street in Manhattan's Lower "
                       'East Side. At a time when plant-based dining was still relatively niche, TeaNY stood out as an '
                       'innovative culinary sanctuary, offering over 80 varieties of premium loose-leaf teas, vegan '
                       'pastries, and cruelty-free sandwiches.</p>\n'
                       '\n'
                       "            <p>Under Tisdale's hands-on management and artistic vision, TeaNY evolved from a "
                       'trendy neighborhood hangout into an international beverage distribution brand, selling bottled '
                       'iced teas and sparkling juices across hundreds of retailers throughout North America and '
                       'Europe. Tisdale also co-authored <em>Teany Book: Stories, Food, Romance, Cartoons and Hundreds '
                       'of Teas</em>, a whimsical creative compilation published by Penguin in 2003 that captured the '
                       "cafe's bohemian spirit. TeaNY operated successfully for over a decade before closing its doors "
                       'following a fire and shifting urban developments in 2015.</p>\n'
                       '\n'
