                       '            <h2>Marriage to Mike Myers: How They Met, Wedding, and Relationship Journey</h2>\n'
                       '            <p>The romantic story between Kelly Tisdale and Mike Myers began in early 2006. At '
                       'the time, Myers had recently separated from his first wife, actress and comedy writer Robin '
                       'Ruzan, after twelve years of marriage. Healing from the personal upheaval of his divorce, '
                       'Myers found immediate solace and intellectual companionship in Tisdale, whose calm demeanor '
                       'and creative spirit resonated deeply with him.</p>\n'
                       '\n'
                       '            <p>The couple dated quietly for roughly four years, purposefully keeping their '
                       'relationship away from paparazzi and tabloid headlines. Unlike many entertainment romances '
                       'that unfold through social media and orchestrated press releases, Myers and Tisdale '
                       'prioritized mutual respect and privacy. Similar to the grounded relationships profiled in our '
                       'retrospective on <a href="/doug-robbie/">celebrity family foundations</a> and <a '
                       'href="/rouba-saadeh/">creative independent partners</a>, their bond flourished because both '
                       'partners valued authentic substance over vanity.</p>\n'
                       '\n'
                       '            <p>In October 2010, Kelly Tisdale and Mike Myers officially married in an '
                       'intimate, private ceremony held in New York City. The wedding was so discreet that news of '
                       "their nuptials did not become public until five months later, in March 2011, when Myers' "
                       'representative officially confirmed the union to media outlets. Friends described the wedding '
                       'as a heartfelt celebration surrounded only by immediate family and closest confidants.</p>\n'
                       '\n'
                       '            <h2>Children and Family Life: Raising Three Kids Away from the Spotlight</h2>\n'
                       '            <p>Over the course of their marriage, Kelly Tisdale and Mike Myers have welcomed '
                       'three children together. Their eldest child, a son named <strong>Spike Alan Myers</strong>, '
                       'was born in September 2011. Two years later, in April 2014, the couple welcomed their first '
                       'daughter, <strong>Sunday Molly Myers</strong>. Their family was completed in November 2015 '
                       'with the arrival of their second daughter, <strong>Paulina Kathleen Myers</strong>.</p>\n'
                       '\n'
                       '            <p>Mike Myers has frequently spoken about how meeting Kelly and becoming a father '
                       'completely altered his worldview and career priorities. In numerous candid interviews, the '
                       'comedy veteran described fatherhood as "the happiest time of my life," explaining that having '
                       'three young children made him far more selective about accepting demanding film roles that '
                       'would take him away from home for extended shoots.</p>\n'
                       '\n'
                       '            <p>Tisdale has played the central role in establishing a stable, grounded '
                       'household routine for their children. The family splits their time between an elegant '
                       'apartment in New York City and a peaceful, scenic country retreat in rural Vermont, ensuring '
                       'their children enjoy an active, nature-oriented childhood rather than an environment dominated '
                       'by Hollywood expectations.</p>\n'
