                       '            <p class="lead-paragraph" style="font-size: 1.18rem; line-height: 1.75; color: '
                       'var(--text-primary); margin-bottom: 24px; font-weight: 500;">Amanda Moye Brown is an '
                       'accomplished American entertainment coordinator, production assistant, and music executive '
                       'assistant who is widely recognized as the longtime wife of celebrated television and film '
                       'actor Wes Brown. While Wes has become a beloved household name across millions of living rooms '
                       'as a quintessential leading man on the Hallmark Channel, as well as through acclaimed dramatic '
                       "roles in HBO's <em>True Blood</em>, <em>Hart of Dixie</em>, and <em>Deception</em>, Amanda has "
                       'built an equally inspiring behind-the-scenes career within premier entertainment studios, '
                       'notably Disney-ABC Television Group.</p>\n'
                       '\n'
                       '            <p>Throughout their eighteen years of marriage, Amanda and Wes Brown have earned '
                       'widespread admiration throughout Hollywood as one of the most stable, genuine couples in the '
                       'industry. Balancing demanding studio production schedules with active parenthood, Amanda Moye '
                       'Brown embodies modern creative resilience and family dedication.</p>\n'
                       '\n'
                       '            <h2>Who Is Amanda Moye Brown?</h2>\n'
                       '            <p>Amanda Moye Brown is a Florida-born entertainment industry professional based '
                       'in Los Angeles, California. With specialized experience in television music administration, '
                       'studio project coordination, and live event production, she has contributed to high-profile '
                       'studio productions under Disney Television Animation and ABC Studios while serving as the '
                       "creative confidante behind Wes Brown's prolific screen career.</p>\n"
                       '\n'
