                       '            <h2>Early Life, Background, and Age</h2>\n'
                       '            <p>Amanda Moye Brown was born in 1983 in Satellite Beach, Florida. Growing up in '
                       'coastal Brevard County, she developed a deep affinity for live theatre, vocal performance, and '
                       'musical storytelling. Her warm Southern upbringing and natural organizational acumen guided '
                       'her toward creative production studies.</p>\n'
                       '\n'
                       '            <p>As of 2026, Amanda Moye Brown is <strong>43 years old</strong>. Early in her '
                       'post-collegiate career, her performance talents led her to work as a character performer at '
                       'Walt Disney World in Orlando, Florida, where she memorably brought classic Disney heroines '
                       'such as Belle from <em>Beauty and the Beast</em> and Princess Jasmine from <em>Aladdin</em> to '
                       'life for thousands of visiting park guests.</p>\n'
                       '\n'
                       '            <p>This early foundation inside the Disney creative ecosystem gave Amanda an '
                       'intimate appreciation of live theatrical pacing, child audiences, and studio storytelling, '
                       'which paved the way for her subsequent transition to executive production offices in Los '
                       'Angeles.</p>\n'
                       '\n'
                       '            <h2>Career at Disney-ABC Television Group and Music Coordination</h2>\n'
                       '            <p>After relocating to Southern California in the mid-2000s, Amanda Moye Brown '
                       'transitioned into studio administration, joining the prestigious <strong>Disney-ABC Television '
                       'Group</strong> in Burbank, California. Serving as an executive assistant and music production '
                       'coordinator, she worked alongside studio composers, music supervisors, and animation '
                       'directors.</p>\n'
                       '\n'
                       '            <p>Her technical credits include contributing to celebrated animated television '
                       "projects and feature specials. She worked within the music department for Disney+'s feature "
                       'animation <em>Phineas and Ferb the Movie: Candace Against the Universe</em> (2020) and the '
                       'acclaimed Pixar-spinoff series <em>Monsters at Work</em> (2021). Her responsibilities '
                       'encompassed licensing tracking, session scheduling for orchestral scoring, and vocal talent '
                       'coordination across demanding broadcast deadlines.</p>\n'
                       '\n'
                       '            <p>In addition to her formal studio roles, Amanda has frequently served as a vital '
                       "sounding board for her husband's television projects. Wes Brown has credited Amanda's "
                       'real-life experiences and sharp sense of humor with inspiring key character interactions in '
                       'his popular Hallmark original holiday movies.</p>\n'
                       '\n'
