                       '            <h2>Marriage to Wes Brown: Romance, Baton Rouge Wedding, and Longtime Bond</h2>\n'
                       '            <p>The love story between Amanda Moye and Wes Brown began during the mid-2000s in '
                       'Los Angeles, where both were navigating early careers in television and film. Wes, born in '
                       "Fort Worth, Texas and raised in Baton Rouge, Louisiana, was immediately drawn to Amanda's "
                       'vibrant Southern warmth, quick wit, and shared Christian values.</p>\n'
                       '\n'
                       '            <p>After several years of steady dating, the couple officially tied the knot on '
                       '<strong>May 2, 2008</strong>, in a joyful, traditional ceremony in Baton Rouge, Louisiana. '
                       'Surrounded by family, Louisiana State University alumni, and close entertainment friends, the '
                       'wedding marked the beginning of an eighteen-year marriage that has remained remarkably free of '
                       'Hollywood turbulence.</p>\n'
                       '\n'
                       "            <p>Shortly after their wedding, Wes Brown's acting career exploded with a "
                       "breakthrough recurring role as Luke McDonald on HBO's cultural phenomenon <em>True Blood</em>, "
                       "followed by leading roles on The CW's <em>Hart of Dixie</em>, ABC's <em>Once Upon a Time</em> "
                       '(as Gaston), and over a dozen beloved Hallmark holiday features including <em>Christmas at '
                       'Graceland</em> and <em>Haul Out the Holly</em>. Through every career transition, Amanda '
                       'remained his steadfast anchor, often joining him on location shoots across the country while '
                       'managing her own production commitments.</p>\n'
                       '\n'
                       '            <p>Their long-standing partnership mirrors the enduring Hollywood unions '
                       'highlighted in our profiles of <a href="/diane-addonizio/">Diane Addonizio</a> and <a '
                       'href="/armstead-edwards/">Armstead Edwards</a>, demonstrating that mutual support and shared '
                       'priorities are the cornerstones of lasting fulfillment.</p>\n'
                       '\n'
                       '            <h2>Children and Family Life: Raising Daughter Merribeth</h2>\n'
                       '            <p>In September 2009, Amanda and Wes Brown welcomed their first and only child, a '
                       'daughter named <strong>Merribeth Brown</strong>. Now a creative teenager in 2026, Merribeth '
                       "shares her parents' deep love of music, outdoor sports, and family traditions.</p>\n"
                       '\n'
                       '            <p>The Brown family resides in a welcoming home in Los Angeles, where they '
                       'prioritize home-cooked Southern meals, church community activities, and frequent trips back to '
