                       'Design in 2008. Eager to expand her formal knowledge of apparel design and commercial '
                       'textiles, she subsequently earned a Post Graduate Diploma in Fashion Design from the renowned '
                       "Istituto Marangoni in Milan, Italy—one of Europe's top fashion academies.</p>\n"
                       "            <p>To further sharpen her executive skills, she completed a Master's degree in "
                       'Fashion and Luxury Brand Management at the European Institute of Design (IED). This rigorous '
                       'combination of technical graphic design and luxury commerce positioned her for senior roles in '
                       'global fashion houses.</p>\n'
                       '\n'
                       '            <h2>Career in Fashion and Work With Elie Saab</h2>\n'
