                       'Alfa MIC in Beirut before transitioning full-time into the fashion industry. Her breakthrough '
                       'came when she joined world-renowned haute couture designer <strong>Elie Saab</strong> as a '
                       'Senior Coordinator and Assistant to the Creative Director.</p>\n'
                       '            <p>At Elie Saab, Saadeh played a hands-on role in coordinating seasonal haute '
                       'couture collections, supervising pattern realization, managing runway showroom presentations '
                       'in Paris, and directing visual communication assets. Her sharp eye for balance and fabric '
