                       '            <p class="lead-paragraph" style="font-size: 1.18rem; line-height: 1.75; color: '
                       'var(--text-primary); margin-bottom: 24px; font-weight: 500;">Jennifer Lynton is an English '
                       'former film production assistant and celebrity spouse who shared nearly three decades of '
                       'marriage with legendary Academy Award-winning actor Sir Anthony Hopkins. Throughout the 1970s, '
                       "1980s, and 1990s, Lynton stood as Hopkins' closest confidante and personal rock, guiding him "
                       'through his early battle for sobriety and accompanying him to international film sets during '
                       'his ascent to Hollywood immortality.</p>\n'
                       '\n'
                       '            <p>While Anthony Hopkins commanded worldwide acclaim for masterpieces like <em>The '
                       'Silence of the Lambs</em> and <em>The Remains of the Day</em>, Jennifer Lynton deliberately '
                       'chose a life of poise, discretion, and privacy. Here is the full, verified biography of '
                       'Jennifer Lynton—covering her background, career, marriage, divorce settlement, and current '
                       'life.</p>\n'
                       '\n'
                       '            <h2>Who Is Jennifer Lynton?</h2>\n'
                       '            <p>Jennifer Lynton is a British former film industry professional who worked for '
                       'Pinewood Studios and independent production companies during the British cinema boom of the '
                       'late 1960s and 1970s. She became known globally as the second wife of Welsh actor Sir Anthony '
                       'Hopkins, remaining married to him for 29 years from 1973 until their divorce in 2002.</p>\n'
                       '\n'
                       '            <!-- Profile Summary Card -->\n'
