                       "            <h2>Jennifer Lynton and Anthony Hopkins' 29-Year Marriage</h2>\n"
                       "            <p>Following the dissolution of Hopkins' first marriage to actress Petronella "
                       'Barker, Jennifer Lynton and Anthony Hopkins were married on January 13, 1973. Their wedding '
                       'took place in an intimate civil ceremony in England.</p>\n'
                       "            <p>The early years of their marriage were profoundly shaped by Hopkins' decision "
                       'to stop drinking in December 1975. Hopkins has publicly acknowledged that Jennifer was '
                       'instrumental in helping him achieve and maintain lasting sobriety, providing him with a '
                       'loving, stable domestic environment in London and the English countryside.</p>\n'
                       '            <p>Her enduring support over nearly three decades mirrors other resilient '
                       'celebrity partners like <a href="/elly-castle/" style="color: var(--accent-crimson); '
                       'font-weight: 600; text-decoration: underline;">Elly Castle</a>, who navigated 21 years '
