                       'font-weight: 600; text-decoration: underline;">Marlene Knaus</a>, who supported Niki Lauda '
                       'through historic career triumphs.</p>\n'
                       '\n'
                       '            <h2>The Reasons Behind Their 2002 Divorce</h2>\n'
                       "            <p>During the 1990s, following Hopkins' historic Best Actor Oscar win for <em>The "
                       'Silence of the Lambs</em> in 1992, his Hollywood workload expanded dramatically. Hopkins '
                       'increasingly relocated his life to Los Angeles and became a naturalized United States citizen '
                       'in 2000, embracing the Californian lifestyle.</p>\n'
                       '            <p>Lynton, however, remained deeply attached to her roots in England and found the '
                       'Hollywood social circuit exhausting. By the late 1990s, the couple was living virtually '
                       'separate lives on opposite sides of the Atlantic Ocean. In 2002, after 29 years of marriage, '
                       'they finalized their divorce amicably on the grounds of living apart. Neither party engaged in '
                       'hostile legal battles or public mudslinging.</p>\n'
                       '\n'
                       '            <h2>Did Jennifer Lynton Have Children?</h2>\n'
                       '            <p>Jennifer Lynton and Anthony Hopkins did not have any biological children '
                       'together during their 29-year marriage. However, through her marriage, Lynton became a '
                       "stepmother to Hopkins' daughter from his first marriage, Abigail Hopkins (born 1968).</p>\n"
                       '\n'
                       '            <h2>Jennifer Lynton Net Worth and Financial Standing</h2>\n'
                       "            <p>As of 2026, Jennifer Lynton's estimated net worth is between <strong>$3 million "
                       'and $5 million</strong>. Her financial independence is anchored by her career in British film '
                       'production and a comprehensive, dignified financial settlement reached upon the conclusion of '
                       'her 29-year marriage to Hopkins.</p>\n'
                       '\n'
                       '            <h2>Where Is Jennifer Lynton Today?</h2>\n'
                       '            <p>Following her 2002 divorce, Jennifer Lynton intentionally withdrew completely '
                       'from the public eye. She chose to reside in the United Kingdom, enjoying a quiet retirement '
                       'surrounded by lifelong friends and family in the English countryside.</p>\n'
                       '            <p>She has consistently declined television interviews, memoirs, and tabloid '
