                       '            <p class="lead-paragraph" style="font-size: 1.18rem; line-height: 1.75; color: '
                       'var(--text-primary); margin-bottom: 24px; font-weight: 500;">Armstead Edwards is an esteemed '
                       'American educator, school administrator, and music business manager best known for his 34-year '
                       'marriage and creative partnership with legendary Grammy-winning soul and R&B icon Patti '
                       'LaBelle. While millions know Patti LaBelle as the fiery "Godmother of Soul," it was Armstead '
                       'Edwards who served as the pragmatic, organized anchor behind her historic crossover solo '
                       'career during the 1970s, 1980s, and 1990s.</p>\n'
                       '\n'
                       '            <p>From his dedication to public education in Philadelphia classrooms to his '
                       'pivotal role managing platinum album campaigns and international stadium tours, Edwards built '
                       'a reputation for integrity, intellectual discipline, and family loyalty. Here is the verified '
                       'biography of Armstead Edwards—detailing his early life, age, career, marriage, peaceful '
                       'divorce, and life today.</p>\n'
                       '\n'
                       '            <h2>Who Is Armstead Edwards?</h2>\n'
                       '            <p>Armstead Edwards is a retired Philadelphia educator, vice principal, and music '
                       'manager. During his career, he balanced two demanding vocations: serving as a school '
                       'administrator helping urban youth in Pennsylvania and managing the complex business, touring, '
                       "and financial operations of his wife's recording empire.</p>\n"
                       '\n'
                       '            <!-- Profile Summary Card -->\n'
                       '            <div style="background: var(--bg-secondary); border: 1px solid '
                       'var(--border-light); border-top: 3px solid var(--accent-crimson); border-radius: '
                       'var(--radius-xs); padding: 24px; margin: 32px 0;">\n'
                       '              <h3 style="font-family: var(--font-serif); font-size: 1.25rem; font-weight: 700; '
                       'margin-bottom: 14px; color: var(--text-primary);">Armstead Edwards: Quick Facts &amp; Bio '
                       'Summary</h3>\n'
                       '              <ul style="list-style: none; padding: 0; margin: 0; display: grid; '
                       'grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; font-size: 0.92rem; '
                       'color: var(--text-secondary);">\n'
                       '                <li><strong style="color: var(--text-primary);">Full Name:</strong> Armstead '
                       'Edwards</li>\n'
                       '                <li><strong style="color: var(--text-primary);">Date of Birth:</strong> April '
                       '1942</li>\n'
                       '                <li><strong style="color: var(--text-primary);">Age:</strong> 84 years old (as '
                       'of 2026)</li>\n'
                       '                <li><strong style="color: var(--text-primary);">Birthplace:</strong> '
                       'Philadelphia, Pennsylvania, USA</li>\n'
                       '                <li><strong style="color: var(--text-primary);">Nationality:</strong> '
                       'American</li>\n'
                       '                <li><strong style="color: var(--text-primary);">Profession:</strong> Educator, '
                       'School Vice Principal &amp; Music Manager</li>\n'
                       '                <li><strong style="color: var(--text-primary);">Former Spouse:</strong> Patti '
                       'LaBelle (m. 1969&ndash;2003)</li>\n'
                       '                <li><strong style="color: var(--text-primary);">Children:</strong> Zuri Kye '
                       'Edwards (plus 4 adopted children)</li>\n'
                       '                <li><strong style="color: var(--text-primary);">Estimated Net Worth:</strong> '
                       '$1.5 Million &ndash; $2.5 Million</li>\n'
                       '              </ul>\n'
                       '            </div>\n'
                       '\n'
                       '            <h2>Early Life, Background, and Age</h2>\n'
                       '            <p>Armstead Edwards was born in April 1942 in Philadelphia, Pennsylvania. Raised '
                       'in a disciplined working-class family, Edwards was taught early on that education was the most '
                       'reliable pathway to community advancement and personal dignity. He pursued higher education in '
                       "Pennsylvania, earning his teaching certifications and master's credentials in educational "
                       'administration.</p>\n'
                       '            <p>As of 2026, Armstead Edwards is <strong>84 years old</strong>. Throughout his '
                       'life in Philadelphia, he remained an admired community elder, known for his calm demeanor, '
                       'sharp intellect, and dedication to mentoring young students.</p>\n'
                       '\n'
                       '            <h2>Career in Education and School Administration</h2>\n'
                       '            <p>Before entering the entertainment industry, Edwards was a full-time '
                       'professional educator in the School District of Philadelphia. He taught junior high school '
                       'students and eventually rose through the ranks to become a respected vice principal.</p>\n'
                       '            <p>Colleagues remembered him as a principled educator who set high standards while '
                       'maintaining deep empathy for students from disadvantaged backgrounds. Even after Patti LaBelle '
                       'achieved worldwide fame, Edwards kept his career in education for many years, refusing to '
                       'abandon his calling to the classroom.</p>\n'
                       '\n'
                       '            <h2>How Armstead Edwards Met Patti LaBelle</h2>\n'
                       '            <p>Armstead Edwards and Patti LaBelle (born Patricia Louise Holte) met in '
                       'Philadelphia during the early 1960s when LaBelle was singing with her breakout vocal group, '
                       'The Bluebelles (later known as Labelle). Edwards was a close family friend and supporter of '
                       "the group's early neighborhood performances.</p>\n"
                       '            <p>Their relationship evolved naturally from mutual respect and deep friendship '
                       'into romance. Over several years, Edwards proposed marriage to Patti three times, but each '
                       'time she hesitated, fearing that the demanding, unpredictable life of a touring singer would '
                       'destroy a marriage.</p>\n'
                       '\n'
                       '            <!-- Middle Editorial Image -->\n'
                       '            <figure style="margin: 36px 0; border: 1px solid var(--border-light); '
                       'border-radius: var(--radius-sm); overflow: hidden; background: var(--bg-secondary);" itemscope '
                       'itemtype="https://schema.org/ImageObject">\n'
                       '              <img itemprop="contentUrl" src="/assets/covers/armstead-edwards-middle.jpg" '
                       'alt="Armstead Edwards and Patti LaBelle attending an industry awards ceremony" width="960" '
                       'height="540" style="width: 100%; height: auto; display: block;" loading="lazy">\n'
                       '              <figcaption itemprop="caption" style="padding: 12px 18px; font-size: 0.85rem; '
                       'color: var(--text-muted); font-style: italic; border-top: 1px solid var(--border-light);">\n'
                       '                Armstead Edwards and wife Patti LaBelle photographed at a major industry '
                       "celebration. Edwards served as LaBelle's trusted personal manager for decades, steering her "
                       'solo R&amp;B career.\n'
                       '              </figcaption>\n'
                       '            </figure>\n'
                       '\n'
                       "            <h2>Patti LaBelle's Proposal and Their 1969 Wedding</h2>\n"
                       '            <p>In 1969, realizing how deeply she loved and relied upon Armstead, Patti turned '
                       'the tables and proposed to him. As Patti famously recounted in her bestselling autobiography '
                       "<em>Don't Block the Blessings</em>, she called Armstead and asked him to marry her; he agreed "
                       'immediately.</p>\n'
                       '            <p>The couple tied the knot on July 23, 1969, in Maryland. Their wedding was '
                       'modest, grounded in simple vows, and followed by a quiet celebratory meal with close loved '
                       'ones—setting the tone for a relationship that always valued domestic reality over '
                       'show-business glitter.</p>\n'
                       '\n'
                       "            <h2>Managing Patti LaBelle's Career and Solo Breakthrough</h2>\n"
                       '            <p>When the pioneering funk-rock trio Labelle disbanded in 1976 following their '
                       'global anthem "Lady Marmalade," Patti faced an uncertain transition into a solo career. '
                       'Recognizing his business acumen and unyielding honesty, Patti asked Armstead to take over as '
                       'her personal manager.</p>\n'
                       '            <p>Edwards stepped into the management role with exceptional focus. He negotiated '
                       'major record deals with Epic and MCA Records, protected her publishing royalties, and '
                       'organized lucrative worldwide concert tours. Under his careful stewardship, LaBelle produced '
                       'timeless crossover solo hits, including "If Only You Knew," "New Attitude," and the iconic '
                       'chart-topping duet "On My Own" with Michael McDonald.</p>\n'
                       '            <p>His understated, effective behind-the-scenes guidance parallels figures like <a '
                       'href="/kaynette-williams/" style="color: var(--accent-crimson); font-weight: 600; '
                       'text-decoration: underline;">Kaynette Williams</a> and <a href="/ian-alexander-sr/" '
                       'style="color: var(--accent-crimson); font-weight: 600; text-decoration: underline;">Ian '
                       'Alexander Sr.</a>, who provided essential professional and emotional foundations for '
                       'high-profile performers.</p>\n'
                       '\n'
                       '            <h2>Children and Family Life</h2>\n'
                       '            <p>In 1973, Armstead and Patti welcomed their biological son, <strong>Zuri Kye '
                       'Edwards</strong>, who grew up immersed in the family business and eventually took over as his '
                       "mother's primary manager in adulthood.</p>\n"
                       '            <p>The couple also demonstrated tremendous family generosity by expanding their '
                       'home to adopt additional children. They adopted two sons, Dodd Stocker-Edwards and Stanley '
                       'Stocker-Edwards, following the death of a family neighbor. Later, following the tragic passing '
                       "of Patti's sister Jackie from cancer, they adopted Jackie's children, William Holte and Stayce "
                       'Holte, raising all five children together in their Philadelphia home.</p>\n'
                       '\n'
                       '            <h2>Their 2000 Separation and 2003 Divorce</h2>\n'
                       '            <p>After more than three decades of marriage, Armstead Edwards and Patti LaBelle '
                       'came to the mutual realization that while their love and respect remained intact, their '
                       'marriage had run its natural course. In 2000, they announced an amicable separation, and their '
                       'divorce was finalized in 2003.</p>\n'
                       '            <p>In her public reflections, Patti emphasized that there was no infidelity, '
                       'financial betrayal, or bitter fighting. "We realized we couldn\'t live together anymore as '
                       'husband and wife, but we promised to stay best friends," Patti stated. Their peaceful split '
                       "remains one of entertainment's most inspiring examples of mature, loving closure.</p>\n"
                       '\n'
                       '            <h2>Armstead Edwards Net Worth and Career Earnings</h2>\n'
                       '            <p>As of 2026, Armstead Edwards has an estimated net worth between <strong>$1.5 '
                       'million and $2.5 million</strong>. His wealth stems from his long career as a public school '
                       "administrator, his executive management commissions during Patti LaBelle's multi-platinum solo "
                       'era, and joint property investments in Pennsylvania.</p>\n'
                       '\n'
                       '            <h2>Where Is Armstead Edwards Now?</h2>\n'
                       '            <p>Today, Armstead Edwards lives comfortably in the Philadelphia area, enjoying '
                       'his retirement away from the music industry. He remains on excellent terms with Patti LaBelle, '
                       'regularly attending family birthdays, Thanksgiving gatherings, and holidays together.</p>\n'
                       "            <p>His son Zuri continues to manage Patti's thriving touring and food product "
                       "enterprises, creating an enduring multi-generational family legacy that reflects Armstead's "
                       'early dedication to family structure and education.</p>\n'
                       '\n'
