                       '                <strong style="color: var(--text-primary); font-size: 1.05rem;">What is Jason '
                       "Clarkson's estimated net worth?</strong>\n"
                       '                <p style="margin-top: 6px; color: var(--text-secondary); line-height: '
                       '1.6;">His net worth is estimated between $500,000 and $750,000 from his independent career in '
                       'construction, logistics, and local commerce.</p>\n'
                       '              </div>\n'
                       '            </div>\n'
