                       'Developer</td></tr>\n'
                       '                <tr style="border-bottom: 1px solid var(--border-light);"><th '
                       'style="text-align: left; padding: 8px 0; color: var(--text-muted);">Former Spouse</th><td '
                       'style="padding: 8px 0;">Sarie Kessler (divorced mid-1990s)</td></tr>\n'
                       '                <tr style="border-bottom: 1px solid var(--border-light);"><th '
                       'style="text-align: left; padding: 8px 0; color: var(--text-muted);">Children</th><td '
                       'style="padding: 8px 0;">Anya Robbie, Lachlan Robbie, Margot Robbie (b. 1990), Cameron '
                       'Robbie</td></tr>\n'
                       '                <tr><th style="text-align: left; padding: 8px 0; color: '
                       'var(--text-muted);">Estimated Net Worth</th><td style="padding: 8px 0; font-weight: 700; '
                       'color: var(--accent-crimson);">$5 Million - $8 Million AUD</td></tr>\n'
                       '              </table>\n'
                       '            </div>\n'
                       '\n'
                       '            <p class="lead-paragraph">Margot Robbie stands today as one of the most bankable '
                       'actresses and prolific producers in global cinema, with blockbuster triumphs ranging from '
                       '<em>The Wolf of Wall Street</em> to <em>Barbie</em> and multiple Academy Award nominations. In '
                       'almost every major profile, Robbie openly credits her single mother, physiotherapist Sarie '
                       'Kessler, for working tirelessly to raise four children on a modest farm in the Gold Coast '
                       "hinterland. Yet behind the actress's celebrated family story lies a figure who has remained "
                       'largely enigmatic: her father, Doug Robbie.</p>\n'
                       '\n'
                       '            <p>A former sugarcane farming magnate and commercial agricultural contractor who '
                       'later transitioned into Queensland residential real estate, Doug Robbie is an intriguing '
                       'figure whose relationship with his famous daughter has generated extensive international '
                       "curiosity. Far from the glamorous red carpets of Los Angeles and London, Doug Robbie's life "
                       'remains rooted in the rugged commercial landscape of rural Australia.</p>\n'
                       '\n'
                       '            <h2>Rural Queensland Roots and the Sugarcane Industry</h2>\n'
                       "            <p>Doug Robbie's origins trace back to the agricultural heartland of regional "
                       'Queensland, Australia. Raised in communities where farming, livestock management, and heavy '
                       'machinery were fundamental parts of daily life, Robbie established himself in the sugarcane '
                       'harvesting sector in the late 1970s and 1980s.</p>\n'
                       '\n'
                       '            <p>Sugarcane cultivation in tropical and subtropical Queensland is a demanding, '
                       'capital-intensive industry requiring meticulous harvest scheduling, transportation logistics, '
                       'and commercial milling contracts. Rather than remaining a small-scale family farmer, Robbie '
                       'developed a reputation as a shrewd contractor. He invested in industrial cutting equipment and '
                       'leased agricultural parcels, coordinating large-scale harvesting operations across the Darling '
                       'Downs and coastal Queensland farming corridors.</p>\n'
                       '\n'
                       '            <h2>Marriage to Sarie Kessler and the Dalby Household</h2>\n'
                       '            <p>In the 1980s, Doug Robbie married Sarie Kessler, a dedicated physiotherapist. '
                       'The couple settled in the regional agricultural hub of Dalby, west of Brisbane, where they '
                       'began raising their family. Over the course of their marriage, they welcomed four children: '
                       'eldest daughter Anya, sons Lachlan and Cameron, and daughter Margot Elise Robbie, born on July '
                       '2, 1990.</p>\n'
                       '\n'
                       '            <div class="inline-related-box" style="background: var(--bg-secondary); '
                       'border-left: 3px solid var(--accent-crimson); padding: 14px 18px; margin: 26px 0; '
                       'border-radius: var(--radius-xs); font-size: 0.95rem;">\n'
                       '              <strong>Related Biography:</strong> <a href="/kathryn-burrhus/" style="color: '
                       'var(--accent-crimson); font-weight: 600; text-decoration: none;">Who Is Kathryn Burrhus? The '
                       "True Story of Stone Cold Steve Austin's First Wife &rarr;</a>\n"
                       '            </div>\n'
                       '\n'
                       "            <p>While Robbie's commercial contracting ventures yielded significant financial "
                       'returns, the demanding nature of his business and differing personal values created strain '
                       'within the household. Much like the early domestic pressures faced by <a '
                       'href="/kathryn-burrhus/" style="color: var(--accent-crimson); font-weight: 600; '
                       'text-decoration: underline;">Kathryn Burrhus</a> during collegiate athletic relocations, the '
                       'demands of commercial enterprise often created geographical and emotional separation within '
                       'the young Robbie home.</p>\n'
                       '\n'
                       '            <h2>The Separation: Growing Up on the Kessler Family Farm</h2>\n'
                       '            <p>When Margot was approximately five years old in the mid-1990s, Doug Robbie and '
                       'Sarie Kessler separated, eventually finalizing their divorce. Following the separation, Sarie '
                       'took primary physical custody of the four children, relocating to the Gold Coast hinterland '
                       'near Currubin Valley.</p>\n'
                       '\n'
                       '            <p>Sarie raised the children largely as a single parent, balancing her work as a '
                       'clinical physiotherapist with domestic responsibilities. Margot and her siblings spent their '
                       "formative years outdoors on their grandparents' property, hunting wild boar, surfing along the "
                       'Gold Coast beaches, and learning self-reliance. In interviews with <em>Vogue</em> and '
                       '<em>Vanity Fair</em>, Margot has recounted how she worked three jobs simultaneously as a '
                       'teenager—making sandwiches at Subway, cleaning surf houses, and working retail—to assist her '
                       'mother with household expenses.</p>\n'
                       '\n'
                       "            <h2>Margot Robbie's Meteoric Rise to Hollywood Superstardom</h2>\n"
                       "            <p>Margot Robbie's determination to achieve financial independence was clear from "
                       'early adolescence. At seventeen, she moved independently to Melbourne, landing a breakout role '
                       'as Donna Freedman on the iconic Australian soap opera <em>Neighbours</em>. By 2011, she '
                       "relocated to the United States, quickly landing the lead in ABC's <em>Pan Am</em> before her "
                       "iconic role opposite Leonardo DiCaprio in Martin Scorsese's <em>The Wolf of Wall Street</em> "
                       '(2013).</p>\n'
                       '\n'
                       "            <p>Robbie's loyalty to her mother became legendary in 2014 when, using her initial "
                       "Hollywood paychecks, she quietly paid off the entirety of Sarie Kessler's home mortgage for "
                       'her 60th birthday. The gesture symbolized the deep gratitude she felt for the parent who had '
                       'sacrificed everything for her education and acting lessons.</p>\n'
                       '\n'
                       '            <div class="inline-related-box" style="background: var(--bg-secondary); '
                       'border-left: 3px solid var(--accent-crimson); padding: 14px 18px; margin: 26px 0; '
                       'border-radius: var(--radius-xs); font-size: 0.95rem;">\n'
                       '              <strong>Related Profile:</strong> <a href="/mia-weier/" style="color: '
                       'var(--accent-crimson); font-weight: 600; text-decoration: none;">Inside the Creative Career '
                       'and Private Life of Mia Weier &rarr;</a>\n'
                       '            </div>\n'
                       '\n'
                       '            <p>The discretion with which Margot preserves her core family boundaries parallels '
                       'the low-profile approach maintained by <a href="/mia-weier/" style="color: '
                       'var(--accent-crimson); font-weight: 600; text-decoration: underline;">Mia Weier</a>, who '
                       'directs creative productions in Los Angeles while fiercely shielding her family life from '
                       'tabloid intrusion.</p>\n'
                       '\n'
                       '            <h2>Transition into Real Estate and Commercial Land Development</h2>\n'
                       '            <p>Following his years in sugarcane contracting, Doug Robbie diversified his '
                       'capital into property investment. Queensland experienced rapid suburban expansion in the 2000s '
                       'and 2010s, with agricultural acreage near Brisbane and the Gold Coast hinterland rezoned for '
                       'residential subdivisions.</p>\n'
                       '\n'
                       '            <p>Robbie acquired parcels of land, participating in commercial subdivisions and '
                       'industrial equipment leasing. Public property records in Queensland indicate his involvement '
                       'in several high-value property transactions, cementing his financial stability independently '
                       "of his children's careers. Friends in regional Queensland describe him as a sharp negotiator "
                       'who understands land valuation, water rights, and developmental zoning.</p>\n'
                       '\n'
                       '            <h2>The Family Dynamic: Distant Yet Respectful</h2>\n'
                       '            <p>Over the years, Australian and international tabloids have occasionally '
                       'sensationalized the dynamic between Doug Robbie and his children. When asked by journalists in '
                       '2016 about her father, Margot offered a candid, measured response, stating that while they '
                       'were not close, there was no active malice, remarking: <em>"He\'s not really a part of my '
                       'life... but there\'s no bad blood."</em></p>\n'
                       '\n'
                       '            <p>However, accounts from extended family members indicate that Doug Robbie has '
                       'maintained occasional contact with his sons, Lachlan and Cameron. Cameron Robbie, who has also '
                       'pursued acting in Australia, has occasionally shared moments with his father on social media. '
                       "Doug has respected his daughter's privacy, turning down lucrative tabloid interview offers and "
                       'maintaining complete discretion regarding her Hollywood career.</p>\n'
                       '\n'
                       '            <h2>Life Today and Estimated Net Worth</h2>\n'
                       '            <p>Today, Doug Robbie resides in regional Queensland, enjoying a comfortable, '
                       'semi-retired lifestyle focused on private investments, golf, and regional community events. He '
                       "has never attempted to leverage Margot's immense international celebrity for commercial "
                       'publicity or personal fame.</p>\n'
                       '\n'
                       '            <p>His estimated net worth is valued between <strong>$5 Million and $8 Million '
                       'AUD</strong>, driven by decades of sugarcane contracting revenues, agricultural equipment '
                       'sales, and residential real estate assets in Queensland. While his relationship with '
                       "Hollywood's leading star remains complex, his independent commercial success in regional "
                       'Australia stands on its own merits.</p>\n'
                       '\n'
                       '            <hr style="margin: 36px 0; border: none; border-top: 1px solid '
                       'var(--border-light);">\n'
                       '\n'
                       '            <div class="faq-section">\n'
                       '              <h3 style="font-family: var(--font-serif); font-size: 1.4rem; margin-bottom: '
                       '16px;">Frequently Asked Questions (FAQs)</h3>\n'
                       '              <div style="margin-bottom: 18px;">\n'
                       '                <strong style="color: var(--text-primary); font-size: 1.05rem;">What is Doug '
                       "Robbie's profession?</strong>\n"
                       '                <p style="margin-top: 6px; color: var(--text-secondary); line-height: '
                       '1.6;">Doug Robbie is an Australian agricultural contractor, former sugarcane farming tycoon, '
                       'and commercial real estate investor based in Queensland.</p>\n'
                       '              </div>\n'
                       '              <div style="margin-bottom: 18px;">\n'
                       '                <strong style="color: var(--text-primary); font-size: 1.05rem;">How many '
                       'children does Doug Robbie have?</strong>\n'
                       '                <p style="margin-top: 6px; color: var(--text-secondary); line-height: 1.6;">He '
                       'has four children with his former wife Sarie Kessler: Anya, Lachlan, Margot Robbie (born '
                       '1990), and Cameron Robbie.</p>\n'
                       '              </div>\n'
                       '              <div style="margin-bottom: 18px;">\n'
                       '                <strong style="color: var(--text-primary); font-size: 1.05rem;">Why did Doug '
                       'Robbie and Sarie Kessler get divorced?</strong>\n'
                       '                <p style="margin-top: 6px; color: var(--text-secondary); line-height: '
                       '1.6;">They divorced in the mid-1990s when Margot was around five years old due to lifestyle '
                       'differences and the strains of his demanding agricultural contracting travel schedule.</p>\n'
                       '              </div>\n'
                       '              <div style="margin-bottom: 18px;">\n'
                       '                <strong style="color: var(--text-primary); font-size: 1.05rem;">Does Margot '
                       'Robbie have a relationship with her father Doug?</strong>\n'
                       '                <p style="margin-top: 6px; color: var(--text-secondary); line-height: '
                       '1.6;">They have a distant relationship. Margot was raised primarily by her single mother Sarie '
                       'and has stated they are not particularly close, though there is no public feud between '
                       'them.</p>\n'
                       '              </div>\n'
                       '              <div style="margin-bottom: 18px;">\n'
                       '                <strong style="color: var(--text-primary); font-size: 1.05rem;">What is Doug '
                       "Robbie's estimated net worth?</strong>\n"
                       '                <p style="margin-top: 6px; color: var(--text-secondary); line-height: '
                       '1.6;">His estimated net worth is between $5 Million and $8 Million AUD, built through his '
                       'agricultural harvesting businesses and long-term land investments in Queensland.</p>\n'
                       '              </div>\n'
