                       'of Law (J.D.)</td></tr>\n'
                       '                <tr style="border-bottom: 1px solid var(--border-light);"><th '
                       'style="text-align: left; padding: 8px 0; color: var(--text-muted);">Profession</th><td '
                       'style="padding: 8px 0;">Attorney, Author, Philanthropic Trustee</td></tr>\n'
                       '                <tr style="border-bottom: 1px solid var(--border-light);"><th '
                       'style="text-align: left; padding: 8px 0; color: var(--text-muted);">Spouse</th><td '
                       'style="padding: 8px 0;">Howard Matthew \'Howie\' Long (m. June 27, 1982)</td></tr>\n'
                       '                <tr style="border-bottom: 1px solid var(--border-light);"><th '
                       'style="text-align: left; padding: 8px 0; color: var(--text-muted);">Children</th><td '
                       'style="padding: 8px 0;">Chris Long (b. 1985), Kyle Long (b. 1988), Howie Long Jr. (b. '
                       '1990)</td></tr>\n'
                       '                <tr><th style="text-align: left; padding: 8px 0; color: '
                       'var(--text-muted);">Estimated Household Net Worth</th><td style="padding: 8px 0; font-weight: '
