                       '              <div style="margin-bottom: 18px;">\n'
                       '                <strong style="color: var(--text-primary); font-size: 1.05rem;">How long have '
                       'Diane Addonizio and Howie Long been married?</strong>\n'
                       '                <p style="margin-top: 6px; color: var(--text-secondary); line-height: '
                       '1.6;">Diane Addonizio and Howie Long have been married for over 42 years. They tied the knot '
                       'on June 27, 1982, after meeting as freshmen at Villanova University in 1978.</p>\n'
                       '              </div>\n'
                       '              <div style="margin-bottom: 18px;">\n'
                       '                <strong style="color: var(--text-primary); font-size: 1.05rem;">What is Diane '
                       "Addonizio's professional and educational background?</strong>\n"
                       '                <p style="margin-top: 6px; color: var(--text-secondary); line-height: '
                       '1.6;">She is a trained attorney. She earned her Bachelor of Arts in Political Science from '
                       'Villanova University in 1982 and subsequently received her Juris Doctor (J.D.) from the USC '
                       'Gould School of Law in Los Angeles, later practicing corporate law.</p>\n'
                       '              </div>\n'
                       '              <div style="margin-bottom: 18px;">\n'
                       '                <strong style="color: var(--text-primary); font-size: 1.05rem;">Who are Diane '
                       "Addonizio and Howie Long's children?</strong>\n"
                       '                <p style="margin-top: 6px; color: var(--text-secondary); line-height: '
                       '1.6;">They have three sons: two-time Super Bowl champion Chris Long (b. 1985), three-time Pro '
                       'Bowl offensive guard Kyle Long (b. 1988), and NFL executive scout Howie Long Jr. (b. '
                       '1990).</p>\n'
                       '              </div>\n'
                       '              <div style="margin-bottom: 18px;">\n'
                       '                <strong style="color: var(--text-primary); font-size: 1.05rem;">What '
                       'philanthropic causes does Diane Addonizio support?</strong>\n'
                       '                <p style="margin-top: 6px; color: var(--text-secondary); line-height: '
                       '1.6;">She is an active trustee for The Chris Long Foundation and the Waterboys clean water '
                       'initiative in East Africa, and serves as an advocate for youth concussion safety and parental '
                       'education in youth sports.</p>\n'
                       '              </div>\n'
                       '              <div style="margin-bottom: 18px;">\n'
                       '                <strong style="color: var(--text-primary); font-size: 1.05rem;">Where do Diane '
                       'and Howie Long live today?</strong>\n'
                       '                <p style="margin-top: 6px; color: var(--text-secondary); line-height: '
                       '1.6;">They reside in Ivy, Virginia, near Charlottesville, maintaining a private country estate '
                       'close to the University of Virginia where their sons attended college.</p>\n'
