                       '            <div class="bio-quick-facts-box" style="background: var(--bg-secondary); border: '
                       '1px solid var(--border-light); border-left: 4px solid var(--accent-crimson); padding: 22px; '
                       'border-radius: var(--radius-xs); margin: 28px 0;">\n'
                       '              <h3 class="quick-facts-title" style="font-family: var(--font-serif); font-size: '
                       '1.3rem; margin-bottom: 14px;">Quick Facts: Roberta \'Bobbi\' Raffel</h3>\n'
                       '              <table class="quick-facts-table" style="width: 100%; border-collapse: collapse; '
                       'font-size: 0.95rem;">\n'
                       '                <tr style="border-bottom: 1px solid var(--border-light);"><th '
                       'style="text-align: left; padding: 8px 0; color: var(--text-muted); width: 35%;">Full '
                       'Name</th><td style="padding: 8px 0; font-weight: 600;">Roberta \'Bobbi\' Raffel '
                       'Lemonis</td></tr>\n'
                       '                <tr style="border-bottom: 1px solid var(--border-light);"><th '
                       'style="text-align: left; padding: 8px 0; color: var(--text-muted);">Date of Birth</th><td '
                       'style="padding: 8px 0;">September 21, 1953</td></tr>\n'
                       '                <tr style="border-bottom: 1px solid var(--border-light);"><th '
                       'style="text-align: left; padding: 8px 0; color: var(--text-muted);">Birthplace</th><td '
                       'style="padding: 8px 0;">Cleveland, Ohio, United States</td></tr>\n'
                       '                <tr style="border-bottom: 1px solid var(--border-light);"><th '
                       'style="text-align: left; padding: 8px 0; color: var(--text-muted);">Nationality</th><td '
                       'style="padding: 8px 0;">American</td></tr>\n'
                       '                <tr style="border-bottom: 1px solid var(--border-light);"><th '
                       'style="text-align: left; padding: 8px 0; color: var(--text-muted);">Profession</th><td '
                       'style="padding: 8px 0;">Fashion Executive, Retail Merchandiser, Private Investor</td></tr>\n'
                       '                <tr style="border-bottom: 1px solid var(--border-light);"><th '
                       'style="text-align: left; padding: 8px 0; color: var(--text-muted);">Spouse</th><td '
                       'style="padding: 8px 0;">Marcus Anthony Lemonis (m. February 17, 2018)</td></tr>\n'
                       '                <tr style="border-bottom: 1px solid var(--border-light);"><th '
                       'style="text-align: left; padding: 8px 0; color: var(--text-muted);">Children</th><td '
                       'style="padding: 8px 0;">Two adult children from a prior marriage</td></tr>\n'
                       '                <tr><th style="text-align: left; padding: 8px 0; color: '
                       'var(--text-muted);">Estimated Personal Net Worth</th><td style="padding: 8px 0; font-weight: '
                       '700; color: var(--accent-crimson);">$5 Million - $10 Million (Combined $500M+)</td></tr>\n'
                       '              </table>\n'
                       '            </div>\n'
                       '\n'
                       '            <p class="lead-paragraph">When entrepreneur and television personality Marcus '
                       "Lemonis evaluates a business on CNBC's acclaimed reality series <em>The Profit</em>, he "
                       "adheres to his famous Three P's doctrine: People, Process, and Product. In his personal and "
                       "professional partnership with Roberta 'Bobbi' Raffel, Lemonis found the embodiment of all "
                       'three. A veteran high-fashion retail executive with decades of wholesale merchandising and '
                       'showroom management experience, Raffel represents far more than a celebrity spouse; she is an '
                       "astute investor and core strategic confidante in Lemonis's vast corporate empire.</p>\n"
                       '\n'
                       '            <p>From their initial encounter at a bustling Las Vegas trade show to their '
                       "high-profile wedding at the Hotel Bel-Air, Raffel's journey reflects resilience, business "
                       'savvy, and a quiet sophistication that has helped solidify some of the most lucrative retail '
                       'acquisitions in the contemporary lifestyle market.</p>\n'
                       '\n'
                       '            <h2>Early Life and Retail Career Foundations</h2>\n'
                       '            <p>Roberta Raffel was born on September 21, 1953, in Cleveland, Ohio. Raised in a '
                       'family with deep commercial roots in the American Midwest, she exhibited an innate instinct '
                       'for consumer aesthetics, textile quality, and sales negotiation from an early age. She '
                       'completed her education with a specialized focus on retail merchandising, marketing, and '
                       'business administration.</p>\n'
                       '            <div class="inline-related-box" style="background: var(--bg-secondary); '
                       'border-left: 3px solid var(--accent-crimson); padding: 14px 18px; margin: 26px 0; '
                       'border-radius: var(--radius-xs); font-size: 0.95rem;">\n'
                       '              <strong>Related Profile:</strong> <a href="/marlene-knaus/" style="color: '
                       'var(--accent-crimson); font-weight: 600; text-decoration: none;">The Biography of Marlene '
                       'Knaus: European Fashion Icon & Life with Niki Lauda &rarr;</a>\n'
                       '            </div>\n'
                       '\n'
                       '            <p>Entering the fashion industry in the 1980s, Raffel built an expansive '
                       'professional network across New York, Los Angeles, and Dallas. Her intuitive understanding of '
                       'high-end tailoring and luxury consumer aesthetics draws parallels to <a href="/marlene-knaus/" '
                       'style="color: var(--accent-crimson); font-weight: 600; text-decoration: underline;">Marlene '
                       'Knaus</a>, whose influential career in Paris and Vienna modeling helped define 1970s European '
                       'couture minimalism.</p> across New York, Los Angeles, and Dallas. She served in senior '
                       'executive capacities, managing luxury apparel showrooms, overseeing wholesale buyer relations, '
                       'and directing trade exhibition marketing. Among her prominent industry roles, she served as a '
                       "key sales and logistics executive for Runaway Pony, a high-end designer children's and women's "
                       'apparel brand known for luxury fabrication and bespoke craftsmanship.</p>\n'
                       '\n'
                       '            <h2>The 2016 Meeting at MAGIC Las Vegas: A Pitch That Changed Everything</h2>\n'
                       '            <p>In 2016, Roberta Raffel attended the MAGIC trade show in Las Vegas, Nevada—one '
                       "of the world's largest and most competitive apparel and retail conventions. Marcus Lemonis, "
                       "CEO of Camping World Holdings and star of CNBC's <em>The Profit</em>, was browsing the "
                       'convention floor scouting potential investment targets to expand his burgeoning fashion '
                       'holding group, ML Fashion Group.</p>\n'
                       '            <p>Spotting Lemonis, Raffel initiated an unscheduled conversation, pitching a '
                       'business concept and recommending that he acquire a specific designer fashion line she was '
                       'representing. Intrigued by her sharp command of unit economics, margins, and supply chain '
                       'logistics, Lemonis agreed to review the proposal. What began as a high-stakes commercial pitch '
                       'quickly evolved into deep mutual respect and a swift romantic connection.</p>\n'
                       '\n'
                       '            <h2>A Modern Romance and 2018 Wedding at Hotel Bel-Air</h2>\n'
                       '            <p>Despite their twenty-year age difference—Raffel was born in 1953, while Lemonis '
                       'was born in 1973—the pair bonded over their shared Midwestern work ethic, passion for '
                       'entrepreneurship, and mutual respect. Lemonis proposed to Raffel on Christmas Day in 2017, '
                       'presenting an engagement ring tucked inside a personalized gift box.</p>\n'
                       '            <p>On February 17, 2018, the couple married in an elegant, intimate ceremony at '
                       'the historic Hotel Bel-Air in Los Angeles, California. The wedding was attended by an '
                       'exclusive circle of family, close friends, and prominent corporate associates. Both bride and '
                       'groom celebrated their union as a mature, deeply grounded partnership founded on equal respect '
                       'and shared ambitions.</p>\n'
                       '\n'
                       '            <h2>Strategic Financial Stake and Camping World Holdings Equity</h2>\n'
                       '            <p>Unlike many spouses in the public eye, Roberta Raffel has maintained direct, '
                       'verified financial skin in the game. Public regulatory filings with the U.S. Securities and '
                       'Exchange Commission (SEC) demonstrate her active involvement as an investor. Following their '
                       'marriage, Raffel acquired 99,094 shares of <strong>Camping World Holdings (NYSE: CWH)</strong> '
                       "on the open market, demonstrating immense confidence in her husband's corporate vision.</p>\n"
                       '            <p>Furthermore, Raffel partnered with Lemonis across multiple retail properties '
                       'under the Marcus Lemonis LLC banner. Her operational journey from trade management into '
                       'independent corporate influence echoes the career trajectory of <a href="/kaynette-williams/" '
                       'style="color: var(--accent-crimson); font-weight: 600; text-decoration: underline;">Kaynette '
                       'Williams</a>, who directed logistical road management before finding long-term fulfillment in '
                       'public education.</p> under the Marcus Lemonis LLC banner, including boutique apparel stores, '
                       'home decor lines, and retail turnaround ventures across Illinois, California, and Florida. Her '
                       'decades of operational insight into buyer psychology and floor management have directly '
                       "informed several of the company's retail restructuring projects.</p>\n"
                       '\n'
                       '            <h2>Blended Family and Philanthropic Endeavors</h2>\n'
                       '            <p>Before meeting Lemonis, Raffel was married and raised two children who are now '
                       'successful adults. Lemonis, who was adopted as an infant in Lebanon and raised in Miami, '
                       "Florida, warmly integrated with Raffel's extended family, frequently praising her children and "
                       'grandchildren across his public channels.</p>\n'
                       '            <p>Together, the couple spearheads extensive philanthropic initiatives through '
                       '<strong>The Lemon-AID Foundation</strong> and <strong>The Business Learning Center</strong>. '
                       'Their charitable giving focuses on providing zero-interest loans, mentorship, and grant '
                       'funding to small businesses, female entrepreneurs, and minority-owned enterprises impacted by '
                       'economic downturns and natural disasters.</p>\n'
                       '\n'
                       "            <h2>Advising on 'The Profit' and Retail Turnaround Ventures</h2>\n"
                       "            <p>Beyond her direct equity in Camping World Holdings, Raffel's extensive "
                       'background in showroom management and retail buying became an invaluable asset for Marcus '
                       "Lemonis during the production of CNBC's <em>The Profit</em>. As Lemonis acquired stakes in "
                       'struggling retail and apparel businesses—including brands such as ML Fashion Group, Runway, '
                       'and artisanal footwear companies—Raffel frequently evaluated inventory turnover, merchandising '
                       'displays, and product line margins behind the scenes.</p>\n'
                       '            <p>Her hands-on experience in wholesale negotiation helped streamline supplier '
                       'relationships, allowing acquisitions to transition from distressed operations to profitable, '
                       'design-forward brands. Industry peers recognize that while Lemonis commands the financial '
                       "restructuring, Raffel's intuitive grasp of luxury consumers provided essential operational "
                       'depth to their retail ventures.</p>\n'
                       '\n'
                       '            <h2>The Lemon-AID Foundation and Small Business Advocacy</h2>\n'
                       '            <p>During the economic turbulence of 2020 and 2021, Roberta Raffel and Marcus '
                       'Lemonis launched <strong>The Lemon-AID Foundation</strong>, pledging over $50 Million in '
                       'direct capital, grants, and zero-interest loans to vulnerable small businesses and women-led '
                       'enterprises across the United States. Rather than acting as distant benefactors, Raffel '
                       'personally reviewed applicant proposals from independent retail boutiques, craft suppliers, '
                       'and apparel manufacturers.</p>\n'
                       '            <p>Her insight into commercial inventory lifecycles and lease negotiations enabled '
                       'dozens of small boutique owners to restructure their supplier debts and survive mandatory '
                       "commercial closures. In public addresses, Lemonis has consistently credited Bobbi's empathetic "
                       'leadership and practical operational counsel with transforming the foundation into one of the '
                       'most effective private small-business recovery vehicles in the country.</p>\n'
                       '\n'
                       '            <h2>Life Today and Net Worth Analysis</h2>\n'
                       '            <p>Today, Roberta Raffel and Marcus Lemonis divide their time between luxury '
                       'residences in Miami Beach, Florida; downtown Chicago, Illinois; and Lake Forest. Raffel '
                       'remains an active, energetic presence at charity galas, fashion previews, and business '
                       'summits, known for her impeccable sartorial taste and approachable demeanor.</p>\n'
                       "            <p>Roberta Raffel's independent net worth is estimated between <strong>$5 Million "
                       'and $10 Million</strong>, anchored by her personal retail earnings, private stock portfolios, '
                       "and real estate equity. Combined with Marcus Lemonis's corporate holdings, the couple commands "
                       'a joint net worth exceeding <strong>$500 Million</strong>.</p>\n'
