                       'style="padding: 8px 0;">Elementary Educator & Mathematics Curriculum Specialist</td></tr>\n'
                       '                <tr style="border-bottom: 1px solid var(--border-light);"><th '
                       'style="text-align: left; padding: 8px 0; color: var(--text-muted);">First Marriage</th><td '
                       'style="padding: 8px 0;">Blake Shelton (m. November 17, 2003 – div. 2006)</td></tr>\n'
                       '                <tr style="border-bottom: 1px solid var(--border-light);"><th '
                       'style="text-align: left; padding: 8px 0; color: var(--text-muted);">Current Spouse</th><td '
                       'style="padding: 8px 0;">Cody Joe Scheck (Rodeo Champion & World Record Steer Roper)</td></tr>\n'
