                       'specialist in the Great Bend, Kansas school system.</p>\n'
                       '              </div>\n'
                       '              <div style="margin-bottom: 18px;">\n'
                       '                <strong style="color: var(--text-primary); font-size: 1.05rem;">Who is '
                       'Kaynette Williams married to now?</strong>\n'
                       '                <p style="margin-top: 6px; color: var(--text-secondary); line-height: '
                       '1.6;">She is married to rodeo champion and world record-holding steer roper Cody Joe Scheck, '
                       'residing on a private agricultural property in Kansas.</p>\n'
                       '              </div>\n'
                       '            </div>\n'
