                       '                <strong style="color: var(--text-primary); font-size: 1.05rem;">How did '
                       'Kathryn Burrhus meet Steve Austin?</strong>\n'
                       '                <p style="margin-top: 6px; color: var(--text-secondary); line-height: '
                       '1.6;">They met in the mid-1980s as undergraduate students at North Texas State University (now '
                       'University of North Texas) in Denton, where Austin was playing college football.</p>\n'
                       '              </div>\n'
                       '              <div style="margin-bottom: 18px;">\n'
                       '                <strong style="color: var(--text-primary); font-size: 1.05rem;">When were '
                       'Kathryn Burrhus and Steve Austin married?</strong>\n'
                       '                <p style="margin-top: 6px; color: var(--text-secondary); line-height: '
                       '1.6;">They were married on November 24, 1990 in Texas, shortly before Austin signed his first '
                       'major professional wrestling contract with World Championship Wrestling (WCW).</p>\n'
                       '              </div>\n'
                       '              <div style="margin-bottom: 18px;">\n'
                       '                <strong style="color: var(--text-primary); font-size: 1.05rem;">Why did '
