                       '            <div class="bio-quick-facts-box" style="background: var(--bg-secondary); border: '
                       '1px solid var(--border-light); border-left: 4px solid var(--accent-crimson); padding: 22px; '
                       'border-radius: var(--radius-xs); margin: 28px 0;">\n'
                       '              <h3 class="quick-facts-title" style="font-family: var(--font-serif); font-size: '
                       '1.3rem; margin-bottom: 14px;">Quick Facts: Mia Weier</h3>\n'
                       '              <table class="quick-facts-table" style="width: 100%; border-collapse: collapse; '
                       'font-size: 0.95rem;">\n'
                       '                <tr style="border-bottom: 1px solid var(--border-light);"><th '
