                       'style="padding: 8px 0;">American</td></tr>\n'
                       '                <tr style="border-bottom: 1px solid var(--border-light);"><th '
                       'style="text-align: left; padding: 8px 0; color: var(--text-muted);">Profession</th><td '
                       'style="padding: 8px 0;">Digital Lifestyle Curator, Sustainable Fashion Consultant</td></tr>\n'
                       '                <tr style="border-bottom: 1px solid var(--border-light);"><th '
                       'style="text-align: left; padding: 8px 0; color: var(--text-muted);">Known For</th><td '
                       'style="padding: 8px 0;">High-Profile Partnership with Olympic Surfer Kanoa Igarashi</td></tr>\n'
                       '                <tr style="border-bottom: 1px solid var(--border-light);"><th '
                       'style="text-align: left; padding: 8px 0; color: var(--text-muted);">Relationship Years</th><td '
                       'style="padding: 8px 0;">2019 – 2023</td></tr>\n'
                       '                <tr><th style="text-align: left; padding: 8px 0; color: '
                       'var(--text-muted);">Estimated Net Worth</th><td style="padding: 8px 0; font-weight: 700; '
                       'color: var(--accent-crimson);">$500,000 - $800,000</td></tr>\n'
                       '              </table>\n'
                       '            </div>\n'
                       '\n'
                       '            <p class="lead-paragraph">In the global arena of professional surfing, '
                       'Japanese-American phenom Kanoa Igarashi stands as an international icon—an elite World Surf '
                       'League (WSL) Championship Tour contender and Olympic Silver Medalist at the Tokyo 2020 Games. '
                       "During the critical four-year window when Igarashi cemented his status among the world's "
                       'premier wave-riders, Mia Weier was a central figure in his personal journey, accompanying him '
                       'across the international surf circuit from Tahiti to Hawaii.</p>\n'
                       '\n'
                       '            <p>Known for her understated elegance, natural coastal California aesthetic, and '
                       'commitment to environmental conservation, Weier earned admiration from surfing communities '
                       'across North America and Japan. Following their quiet parting in 2023, she has continued to '
                       'build an independent profile centered on sustainable living, fashion curation, and ocean '
                       'conservation.</p>\n'
                       '\n'
                       '            <h2>Early Life and Coastal California Roots</h2>\n'
                       '            <p>Mia Weier was born in 1999 in Santa Barbara, California, a coastal community '
                       'renowned for its historic surf breaks and environmentally conscious culture. Growing up along '
                       'the Pacific coastline, she developed a passion for ocean ecology, swimming, and wellness from '
                       'an early age.</p>\n'
                       '            <p>Weier pursued studies in communications and environmental studies, developing a '
                       'keen eye for visual aesthetics, photography, and sustainable apparel. Friends from Southern '
                       'California describe her as grounded, artistic, and deeply committed to natural lifestyle '
                       'practices.</p>\n'
                       '\n'
                       '            <h2>Meeting Kanoa Igarashi and the International Surf Tour</h2>\n'
                       '            <p>In 2019, Mia crossed paths with Kanoa Igarashi through mutual friends in the '
                       'Southern California surf scene. Born in Huntington Beach to Japanese surfing parents, Igarashi '
                       'was already competing at the highest tiers of the WSL Championship Tour.</p>\n'
                       '            <div class="inline-related-box" style="background: var(--bg-secondary); '
                       'border-left: 3px solid var(--accent-crimson); padding: 14px 18px; margin: 26px 0; '
                       'border-radius: var(--radius-xs); font-size: 0.95rem;">\n'
                       '              <strong>Related Biography:</strong> <a href="/marlene-knaus/" style="color: '
                       'var(--accent-crimson); font-weight: 600; text-decoration: none;">Who Is Marlene Knaus? The '
                       "Biography of Niki Lauda's First Wife &rarr;</a>\n"
                       '            </div>\n'
                       '\n'
                       '            <p>Their connection quickly developed into a prominent partnership. Mia '
                       'accompanied Igarashi on grueling world tour stops across Tahiti, Portugal, and Australia. Her '
                       'role supporting an elite athlete through world title campaigns draws natural comparisons to <a '
                       'href="/marlene-knaus/" style="color: var(--accent-crimson); font-weight: 600; text-decoration: '
                       'underline;">Marlene Knaus</a> during Niki Lauda\'s Formula One Grand Prix seasons.</p> Mia '
                       "accompanied Igarashi on grueling world tour stops, including the Billabong Pro Teahupo'o in "
                       "Tahiti, the Vans Triple Crown of Surfing on Oahu's North Shore, the MEO Rip Curl Pro in "
                       'Portugal, and the Rip Curl Pro Bells Beach in Australia. Her calming influence provided '
                       'Igarashi with emotional equilibrium amid the intense pressures of competitive world '
                       'rankings.</p>\n'
                       '\n'
                       '            \n'
                       '\n'
                       '            <h2>The High-Performance Demands of the WSL Championship Tour</h2>\n'
                       '            <p>Professional surfing at the World Surf League (WSL) Championship Tour level is '
                       'one of the most physically and logistically demanding disciplines in global sports. Surfers do '
                       'not compete on standard schedules; instead, competitions rely on multi-week waiting periods '
                       'that track unpredictable ocean swell forecasts, wind directions, and tidal patterns across '
                       'remote global locations. During their four-year partnership, Mia Weier was an integral part of '
                       "Kanoa Igarashi's traveling support entourage.</p>\n"
                       "            <p>From the heavy, dangerous reef barrels of Teahupo'o in French Polynesia to the "
                       'freezing waters of Peniche, Portugal, Weier helped manage the logistical challenges of '
                       'international travel, nutritional regimens, and board testing alongside famed surfboard shaper '
                       'Channel Islands Surfboards in Santa Barbara. Her presence provided Igarashi with psychological '
                       'balance and domestic normalcy in high-pressure competition environments where a single wave '
                       'score can determine a year-long world title campaign.</p>\n'
                       '\n'
                       '            <h2>The Tokyo 2020 Olympic Silver Medal Journey</h2>\n'
                       "            <p>The defining athletic milestone of Igarashi's career occurred during the Tokyo "
                       '2020 Olympic Games (held in the summer of 2021), where surfing made its historic debut as an '
                       'official Olympic sport at Tsurigasaki Beach in Chiba, Japan. Representing Japan, Igarashi '
                       'faced immense national expectations.</p>\n'
                       '            <p>In an unforgettable semifinal heat, Igarashi executed a daring aerial maneuver '
                       'to defeat world champion Gabriel Medina, securing the Olympic Silver Medal for host nation '
                       'Japan. Throughout the intense training camps and strict COVID-19 bio-bubble protocols leading '
                       'up to the Games, Mia served as his principal domestic supporter, celebrating his historic '
                       'achievement alongside his family.</p>\n'
                       '\n'
                       '            <h2>Quiet 2023 Separation and Mature Independence</h2>\n'
                       '            <p>In mid-2023, after four years together, Mia Weier and Kanoa Igarashi quietly '
                       'ended their relationship. Unlike many young influencer couples, neither party engaged in '
                       'public drama, cryptic social media attacks, or tabloid discussions.</p>\n'
                       '            <p>Both removed shared couple photographs from their respective platforms with '
                       'mutual respect, choosing to focus on their respective professional paths without '
                       'animosity.</p>\n'
                       '\n'
                       '            <h2>Commitment to Marine Conservation and Coastal Ecosystems</h2>\n'
                       '            <p>Growing up on the beaches of Santa Barbara, Mia Weier developed a lifelong '
                       'dedication to marine biology and ocean stewardship that extends far beyond surfing culture. '
                       'She has actively volunteered with California marine non-profit organizations focused on giant '
                       'kelp forest restoration, coastal wetland preservation, and marine debris cleanup along the '
                       'Channel Islands coastline.</p>\n'
                       '            <p>In her professional creative work, Weier collaborates exclusively with '
                       'sustainable lifestyle brands that champion biodegradable packaging, ocean-recovered plastic '
                       'textiles, and reef-safe sunscreen formulations. Her authentic connection to ocean ecology has '
                       'made her a respected young voice among eco-conscious California creatives seeking to protect '
                       'fragile marine habitats for future generations.</p>\n'
                       '\n'
                       '            <h2>Visual Storytelling and Coastal Photography Portfolio</h2>\n'
                       '            <p>In addition to her environmental advocacy, Mia Weier has cultivated an '
                       'evocative visual portfolio as a coastal lifestyle photographer and creative director. Drawing '
                       'inspiration from 1970s analog surf photography and the pristine natural landscapes of '
                       "California's Central Coast, her work captures unposed, intimate moments of ocean culture, sea "
                       'life, and coastal flora.</p>\n'
                       '            <p>Her editorial features and digital photo essays have been showcased by '
                       'independent environmental publications and ethical surf collectives, celebrating marine '
                       'minimalism and mindful living. Collectors and collaborators commend her authentic aesthetic, '
                       'which avoids commercial superficiality in favor of deep environmental reverence.</p>\n'
                       '\n'
                       '            <h2>Creative Pursuits, Ocean Stewardship, and Life Today</h2>\n'
                       '<h2>Brand Collaborations and Environmental Advocacy</h2>\n'
                       '            <p>In her ongoing creative work, Mia Weier partners with ethical outdoor brands, '
                       'organic skincare formulations, and sustainable surf labels that share her environmental '
                       'philosophy. Refusing commercial sponsorships that rely on synthetic microplastics or '
                       'petroleum-derived packaging, she has used her digital influence to promote consumer '
                       'mindfulness, zero-waste beach culture, and marine habitat awareness across California.</p>\n'
                       '            <p>Her collaborative projects emphasize long-term ecological balance over '
                       'fast-fashion consumption, resonating with a growing demographic of conscious coastal residents '
                       'who seek authenticity and nature-centric design.</p>\n'
                       '            <p>Today, Mia Weier resides in Southern California, focusing on creative '
                       'consulting, sustainable fashion curation, and ocean conservation projects. Her independent '
                       'creative aesthetic and environmental focus parallels that of <a href="/roberta-raffel/" '
                       'style="color: var(--accent-crimson); font-weight: 600; text-decoration: underline;">Roberta '
                       'Raffel</a>, who championed ethical curation and boutique apparel throughout her career.</p>, '
                       'focusing on creative consulting, sustainable fashion curation, and ocean conservation '
                       'projects. She works with eco-conscious lifestyle brands that prioritize ocean-safe materials, '
                       'ethical manufacturing, and clean beauty.</p>\n'
                       '            <p>Her personal net worth is estimated between <strong>$500,000 and '
                       '$800,000</strong>, earned through creative brand partnerships, digital marketing consulting, '
                       'and lifestyle curation projects.</p>\n'
